use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let (a, b) = input.as_array().unwrap();
    let a_str = a[0].as_str().unwrap();
    let b_str = b[0].as_str().unwrap();
    let mut a_chars = a_str.chars().collect::<Vec<char>>();
    let mut b_chars = b_str.chars().collect::<Vec<char>>();
    a_chars.sort_unstable();
    b_chars.sort_unstable();
    a_chars.dedup();
    b_chars.dedup();
    a_chars == b_chars
}
